&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;FAQ officielle&lt;a class=&quot;headeranchor&quot; id=&quot;FAQ_officielle_0&quot; href=&quot;#FAQ_officielle_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq-Officielle.html&quot; title=&quot;FAQ de Paizo&quot;&gt;Page de garde&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs.html&quot; title=&quot;FAQ du Manuel des joueurs&quot;&gt;Manuel des joueurs&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Armes-Et-&#201;quipement.html&quot; title=&quot;FAQ d&amp;#39;Armes et &#233;quipement&quot;&gt;Armes et &#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-La-Guerre.html&quot; title=&quot;FAQ de l&amp;#39;Art de la guerre&quot;&gt;l&#39;Art de la guerre&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-La-Magie.html&quot; title=&quot;FAQ de l&amp;#39;Art de la magie&quot;&gt;l&#39;Art de la magie&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-Lintrigue.html&quot; title=&quot;FAQ- de l&amp;#39;Art de l&amp;#39;intrigue&quot;&gt;l&#39;Art de l&#39;intrigue&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Aventures-Occultes.html&quot; title=&quot;FAQ d&amp;#39;Aventures occultes&quot;&gt;Aventures occultes&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Bestiaire.html&quot; title=&quot;FAQ du Bestiaire&quot;&gt;Bestiaire&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Campagnes-Mythiques.html&quot; title=&quot;FAQ de Campagnes mythiques&quot;&gt;Campagnes mythiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Guide-De-Campagne.html&quot; title=&quot;FAQ du Guide de campagne&quot;&gt;Guide de campagne&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---Classes-Avanc&#233;es.html&quot; title=&quot;FAQ du Manuel des joueurs - Classes avanc&#233;es&quot;&gt;Manuel des joueurs &lt;br/&gt;- Classes avanc&#233;es&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;Manuel des joueurs &lt;br/&gt;- R&#232;gles avanc&#233;es&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Races.html&quot; title=&quot;FAQ du Manuel des races&quot;&gt;Manuel des races&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Pathfinder-Unchained.html&quot; title=&quot;FAQ de Pathfinder unchained&quot;&gt;Pathfinder unchained&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;b&gt;&lt;i&gt;Voir la &lt;a class=&quot;externallink&quot; href=&quot;https://paizo.com/paizo/faq/v5748nruor1gh&quot; title=&quot;version originale&quot; target=&quot;_blank&quot;&gt;version originale&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Races&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#1&quot; title=&quot;Demi-elfe, parangon soudain :&quot;&gt;Demi-elfe, &lt;i&gt;parangon soudain&lt;/i&gt; :&lt;/a&gt; Puis-je lancer &lt;i&gt;parangon soudain&lt;/i&gt; plusieurs fois par jour pour b&#233;n&#233;ficier d&#39;effets diff&#233;rents ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#2&quot; title=&quot;Demi-orque, Convocations f&#233;roces :&quot;&gt;Demi-orque, Convocations f&#233;roces :&lt;/a&gt; Comment cette capacit&#233; est-elle cens&#233;e fonctionner si une cr&#233;ature dispara&#238;t lorsqu&#39;elle atteint 0 pv ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#3&quot; title=&quot;Demi-orque, Vision dans le noir d&#233;velopp&#233;e :&quot;&gt;Demi-orque, Vision dans le noir d&#233;velopp&#233;e :&lt;/a&gt; Puis-je s&#233;lectionner ce trait racial si l&#39;un de mes traits raciaux remplace vision dans le noir ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#4&quot; title=&quot;Halfelin, Guerrier &#224; la fronde :&quot;&gt;Halfelin, Guerrier &#224; la fronde :&lt;/a&gt; Avec quels types de fronde cette capacit&#233; de rechargement fonctionne-t-elle ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#5&quot; title=&quot;Humain :&quot;&gt;Humain :&lt;/a&gt; O&#249; se trouve le sort &lt;i&gt;pure strain&lt;/i&gt; du lignage d&#39;ensorceleur imp&#233;rieux ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Dons&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;internallink&quot; href=&quot;#6&quot; title=&quot;Serviteur c&#233;leste :&quot;&gt;Serviteur c&#233;leste :&lt;/a&gt; Ce don remplace-t-il les DV, jets de sauvegarde et rangs de comp&#233;tence de ma cr&#233;ature compagnon &#224; cause du changement de type ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;R&#233;ponses sur les races&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;ponses_sur_les_races_6&quot; href=&quot;#R&#233;ponses_sur_les_races_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;1&quot; href=&quot;#1&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Demi-elfe, &lt;i&gt;parangon soudain&lt;/i&gt; : Puis-je lancer &lt;i&gt;parangon soudain&lt;/i&gt; plusieurs fois par jour pour b&#233;n&#233;ficier d&#39;effets diff&#233;rents ?&lt;a class=&quot;headeranchor&quot; id=&quot;Demi-elfe_parangon_soudain_:_Puis-je_lancer_parangon_soudain_plusieurs_fois_par_jour_pour_b&#233;n&#233;ficier_deffets_diff&#233;rents__0&quot; href=&quot;#Demi-elfe_parangon_soudain_:_Puis-je_lancer_parangon_soudain_plusieurs_fois_par_jour_pour_b&#233;n&#233;ficier_deffets_diff&#233;rents__0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Non. La premi&#232;re fois qu&#39;un personnage lance &lt;u&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parangon-Soudain.html&quot; title=&quot;Parangon soudain&quot;&gt;parangon soudain&lt;/a&gt;&lt;/i&gt;&lt;/u&gt; chaque jour, il doit choisir un don et prendre toutes les d&#233;cisions qui vont avec. Une fois ce choix fait, il est fig&#233; pour la journ&#233;e et toutes les autres incantations doivent se baser sur ce choix.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;2&quot; href=&quot;#2&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Demi-orque, Convocations f&#233;roces : Comment cette capacit&#233; est-elle cens&#233;e fonctionner si une cr&#233;ature dispara&#238;t lorsqu&#39;elle atteint 0 pv ?&lt;a class=&quot;headeranchor&quot; id=&quot;Demi-orque_Convocations_f&#233;roces_:_Comment_cette_capacit&#233;_est-elle_cens&#233;e_fonctionner_si_une_cr&#233;ature_dispara&#238;t_lorsquelle_atteint_A_pv__1&quot; href=&quot;#Demi-orque_Convocations_f&#233;roces_:_Comment_cette_capacit&#233;_est-elle_cens&#233;e_fonctionner_si_une_cr&#233;ature_dispara&#238;t_lorsquelle_atteint_A_pv__1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La cr&#233;ature convoqu&#233;e ne dispara&#238;t pas &#224; 0 pv, mais lorsqu&#39;elle meurt (lorsqu&#39;elle atteint un nombre de points de vie n&#233;gatifs &#233;gal &#224; sa valeur de Constitution). &lt;i&gt;(Retour au &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocations-F&#233;roces.html&quot; title=&quot;Convocations f&#233;roces&quot;&gt;don&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;3&quot; href=&quot;#3&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Demi-orque, Vision dans le noir d&#233;velopp&#233;e : Puis-je s&#233;lectionner ce trait racial si l&#39;un de mes traits raciaux remplace vision dans le noir ?&lt;a class=&quot;headeranchor&quot; id=&quot;Demi-orque_Vision_dans_le_noir_d&#233;velopp&#233;e_:_Puis-je_s&#233;lectionner_ce_trait_racial_si_lun_de_mes_traits_raciaux_remplace_vision_dans_le_noir__2&quot; href=&quot;#Demi-orque_Vision_dans_le_noir_d&#233;velopp&#233;e_:_Puis-je_s&#233;lectionner_ce_trait_racial_si_lun_de_mes_traits_raciaux_remplace_vision_dans_le_noir__2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Non. Le personnage doit poss&#233;der le trait racial vision dans le noir pour pouvoir s&#233;lectionner le trait racial &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html#VISIONDANSLENOIRDEVELOPEE&quot; title=&quot;Les demi-orques&quot;&gt;vision dans le noir d&#233;velopp&#233;e&lt;/a&gt;&lt;/u&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;4&quot; href=&quot;#4&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Halfelin, Guerrier &#224; la fronde : Avec quels types de fronde cette capacit&#233; de rechargement fonctionne-t-elle ?&lt;a class=&quot;headeranchor&quot; id=&quot;Halfelin_Guerrier_&#224;_la_fronde_:_Avec_quels_types_de_fronde_cette_capacit&#233;_de_rechargement_fonctionne-t-elle__3&quot; href=&quot;#Halfelin_Guerrier_&#224;_la_fronde_:_Avec_quels_types_de_fronde_cette_capacit&#233;_de_rechargement_fonctionne-t-elle__3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La capacit&#233; &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html#GUERRIERALAFRONDE&quot; title=&quot;Les halfelins&quot;&gt;guerrier &#224; la fronde&lt;/a&gt;&lt;/u&gt; dit : &#171; Ceux qui poss&#232;dent ce trait racial peuvent recharger cette arme par une action libre. &#187; Il ne dit pas &#171; n&#39;importe quel type de fronde &#187; ou &#171; toutes les frondes &#187;, seulement &#171; cette arme &#187;. La capacit&#233; n&#39;affecte que les &lt;a class=&quot;pagelink&quot; href=&quot;Fronde-(Arme).html&quot; title=&quot;Fronde&quot;&gt;frondes&lt;/a&gt; standards, pas le &lt;a class=&quot;pagelink&quot; href=&quot;Fustibale-Halfelin-(Arme).html&quot; title=&quot;Fustibale halfelin&quot;&gt;fustibale halfelin&lt;/a&gt; ou tout autre type de fronde.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;border-top:1px dashed #4b3124&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;5&quot; href=&quot;#5&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;&lt;strike&gt;Humain : O&#249; se trouve le sort &lt;i&gt;pure strain&lt;/i&gt; du lignage d&#39;ensorceleur imp&#233;rieux ?&lt;a class=&quot;headeranchor&quot; id=&quot;_Humain_:_O&#249;_se_trouve_le_sort_pure_strain_du_lignage_densorceleur_imp&#233;rieux__4&quot; href=&quot;#_Humain_:_O&#249;_se_trouve_le_sort_pure_strain_du_lignage_densorceleur_imp&#233;rieux__4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le sort &lt;i&gt;pure strain&lt;/i&gt; a &#233;t&#233; abandonn&#233; lors du d&#233;veloppement mais son nom n&#39;a pas &#233;t&#233; retir&#233; de la liste des &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Imp&#233;rieux.html&quot; title=&quot;Lignage Imp&#233;rieux&quot;&gt;sorts bonus&lt;/a&gt;&lt;/u&gt;. Remplacez &lt;i&gt;pure strain&lt;/i&gt; par &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champ-De-Force.html&quot; title=&quot;Champ de force&quot;&gt;champ de force&lt;/a&gt;&lt;/i&gt;.  
Cela a &#233;t&#233; not&#233; pour une future r&#233;impression du &lt;i&gt;Manuel des races&lt;/i&gt;.&lt;/strike&gt; Les textes ont &#233;t&#233; corrig&#233;s sur ce point.&lt;br /&gt;&lt;br /&gt;
&lt;h2 class=&quot;separator&quot;&gt;R&#233;ponses sur les dons&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;ponses_sur_les_dons_7&quot; href=&quot;#R&#233;ponses_sur_les_dons_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;6&quot; href=&quot;#6&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Serviteur c&#233;leste : Ce don remplace-t-il les DV, jets de sauvegarde et rangs de comp&#233;tence de ma cr&#233;ature compagnon &#224; cause du changement de type ?&lt;a class=&quot;headeranchor&quot; id=&quot;Serviteur_c&#233;leste_:_Ce_don_remplace-t-il_les_DV_jets_de_sauvegarde_et_rangs_de_comp&#233;tence_de_ma_cr&#233;ature_compagnon_&#224;_cause_du_changement_de_type__5&quot; href=&quot;#Serviteur_c&#233;leste_:_Ce_don_remplace-t-il_les_DV_jets_de_sauvegarde_et_rangs_de_comp&#233;tence_de_ma_cr&#233;ature_compagnon_&#224;_cause_du_changement_de_type__5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Non. Tout ce que &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-C&#233;leste.html&quot; title=&quot;Serviteur c&#233;leste&quot;&gt;Serviteur c&#233;leste&lt;/a&gt;&lt;/u&gt; fait est changer le type de la cr&#233;ature en &#171; cr&#233;ature magique &#187; (ce qui l&#39;immunise contre les capacit&#233;s qui n&#39;affectent que les animaux) et lui donne les capacit&#233;s de l&#39;arch&#233;type simple &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATURECELESTE&quot; title=&quot;Les arch&#233;types&quot;&gt;cr&#233;ature c&#233;leste&lt;/a&gt; (qui ne change rien d&#39;autre que ce qui est d&#233;j&#224; indiqu&#233; dans l&#39;arch&#233;type).
